"""Generate docs/CYPHER.md from cypher/*.cypher (submission rule: list the Cypher the product depends on)."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main() -> None:
    out = [
        "# Cypher queries Git0 depends on",
        "",
        "Generated by `make cypher-docs` from [`cypher/`](../cypher). Do not edit by hand.",
        "",
    ]
    for path in sorted((ROOT / "cypher").glob("*.cypher")):
        lines = path.read_text().splitlines()
        notes = [ln[2:].strip() for ln in lines if ln.startswith("//") and not ln.startswith("// name:")]
        body = "\n".join(ln for ln in lines if not ln.startswith("//")).strip()
        out += [f"## `{path.stem}`", "", *notes, "", "```cypher", body, "```", ""]
    (ROOT / "docs" / "CYPHER.md").write_text("\n".join(out))
    print(f"wrote docs/CYPHER.md ({len(list((ROOT / 'cypher').glob('*.cypher')))} queries)")


if __name__ == "__main__":
    main()
